changeSet.sql:
DO $cutover$
DECLARE
    partman_schema text;
    configured_template text;
    template_oid regclass;
    config_count integer;
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_partition_tree('public.auth_event') p
        LEFT JOIN pg_attribute a ON a.attrelid = p.relid AND a.attname = 'details' AND NOT a.attisdropped
        WHERE a.atttypid IS DISTINCT FROM 'jsonb'::regtype
    ) THEN
        RAISE EXCEPTION 'Native Hibernate JSON cutover requires jsonb details on every auth_event partition';
    END IF;
    SELECT n.nspname INTO partman_schema FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_partman';
    IF partman_schema IS NULL THEN
        RAISE EXCEPTION 'Native Hibernate JSON cutover requires the baseline pg_partman configuration';
    END IF;
    EXECUTE format('SELECT count(*), min(template_table) FROM %I.part_config WHERE parent_table = $1', partman_schema)
        INTO config_count, configured_template USING 'public.auth_event';
    IF config_count <> 1 OR configured_template IS NULL THEN
        RAISE EXCEPTION 'Native Hibernate JSON cutover requires one configured auth_event template';
    END IF;
    template_oid := to_regclass(configured_template);
    IF template_oid IS NULL OR NOT EXISTS (
        SELECT 1 FROM pg_class c JOIN pg_attribute a ON a.attrelid = c.oid
        WHERE c.oid = template_oid AND c.relkind = 'r' AND NOT c.relispartition
          AND a.attname = 'details' AND NOT a.attisdropped AND a.atttypid = 'jsonb'::regtype
    ) OR EXISTS (SELECT 1 FROM pg_inherits WHERE inhrelid = template_oid OR inhparent = template_oid) THEN
        RAISE EXCEPTION 'Native Hibernate JSON cutover requires a standalone jsonb auth_event template';
    END IF;

    ALTER TABLE public.auth_event ALTER COLUMN details TYPE text USING
        CASE WHEN details IS NULL OR jsonb_typeof(details) = 'null' THEN NULL
             WHEN jsonb_typeof(details) = 'string' THEN details #>> '{}' ELSE details::text END;
    ALTER TABLE public.config_audit_event
        ALTER COLUMN old_value TYPE text USING
            CASE WHEN old_value IS NULL OR jsonb_typeof(old_value) = 'null' THEN NULL
                 WHEN jsonb_typeof(old_value) = 'string' THEN old_value #>> '{}' ELSE old_value::text END,
        ALTER COLUMN new_value TYPE text USING
            CASE WHEN new_value IS NULL OR jsonb_typeof(new_value) = 'null' THEN NULL
                 WHEN jsonb_typeof(new_value) = 'string' THEN new_value #>> '{}' ELSE new_value::text END;
    ALTER TABLE public.project_field ALTER COLUMN options TYPE text USING
        CASE WHEN options IS NULL OR jsonb_typeof(options) = 'null' THEN NULL
             WHEN jsonb_typeof(options) = 'string' THEN options #>> '{}' ELSE options::text END;
    ALTER TABLE public.connection_audit ALTER COLUMN detail TYPE text USING
        CASE WHEN detail IS NULL OR jsonb_typeof(detail) = 'null' THEN NULL
             WHEN jsonb_typeof(detail) = 'string' THEN detail #>> '{}' ELSE detail::text END;
    EXECUTE format('ALTER TABLE %s ALTER COLUMN details TYPE text USING '
        || 'CASE WHEN details IS NULL OR jsonb_typeof(details) = ''null'' THEN NULL '
        || 'WHEN jsonb_typeof(details) = ''string'' THEN details #>> ''{}'' ELSE details::text END', template_oid);
END
$cutover$;
